</div></div></section></main>@include('welcome.includes.footer')<div aria-labelledby="modalTitle" aria-modal="true" class="modal" id="modal" role="dialog"><div class="dialog"><button aria-label="Close" class="close" id="closeModal">×</button><h2 id="modalTitle"></h2><div id="modalBody"></div></div></div><script>const courses=@json($courseData);const modal=document.getElementById('modal'),body=document.getElementById('modalBody'),title=document.getElementById('modalTitle');let activeIndex=0,previousFocus;function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function closeModal(){modal.classList.remove('show');body.innerHTML='';if(previousFocus)previousFocus.focus()}const feeByIndex=@json($courseFees);function openModal(idx,action){activeIndex=idx;previousFocus=document.activeElement;const c=courses[idx];modal.classList.add('show');if(action==='details'){title.textContent=c.title;body.innerHTML='<img class="details-img" src="'+escapeHtml(c.image)+'" alt="'+escapeHtml(c.alt)+'"><p>'+escapeHtml(c.desc)+'</p><p><strong>Duration:</strong> '+escapeHtml(c.duration)+'</p><h3>Proposed Course Modules</h3><ol class="modules">'+c.modules.map(m=>'<li>'+escapeHtml(m)+'</li>').join('')+'</ol><p class="note">Indicative module outline for website presentation; final syllabus to be confirmed by Rainbow Automation.</p><button class="btn" id="askNow">Inquiry for this Course ↗</button>';document.getElementById('askNow').onclick=()=>openModal(idx,'inquiry')}else{title.textContent='Course Inquiry';body.innerHTML='<p><strong>Selected course:</strong> '+escapeHtml(c.title)+'</p><form id="inquiry"><div class="form-grid"><label class="field">Name *<input name="name" required></label><label class="field">Phone *<input name="phone" required></label><label class="field full">Email<input name="email" type="email"></label><label class="field full">Message<textarea name="message" rows="4" placeholder="Please share schedule, fees and enrollment details."></textarea></label></div><button class="btn" style="margin-top:20px" type="submit">Send Inquiry ↗</button><p class="form-note">Our training team will contact you with schedule, fees and enrollment details.</p></form>';document.getElementById('inquiry').onsubmit=function(e){e.preventDefault();const form=this,btn=form.querySelector('button[type=submit]'),note=form.querySelector('.form-note'),f=new FormData(form);f.append('course',c.id);btn.disabled=true;btn.textContent='Sending...';const fail=msg=>{note.textContent=msg;note.style.color='#d63c4f';btn.disabled=false;btn.textContent='Send Inquiry ↗'};fetch('{{route('courseInquiry')}}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:f}).then(r=>r.json().then(d=>({ok:r.ok,status:r.status,d})).catch(()=>({ok:false,status:r.status,d:{}}))).then(({ok,status,d})=>{if(ok&&d.success){body.innerHTML='<div class="info-banner" style="margin-top:0"><strong>Thank you, '+escapeHtml(f.get('name'))+'!</strong><p>'+escapeHtml(d.message)+'</p></div>';return}if(status===419)return fail('Your session has expired. Please refresh the page and try again.');if(status===429)return fail('Too many inquiries. Please wait a minute and try again.');fail(d.errors?Object.values(d.errors).flat().join(' '):(d.message||'Something went wrong. Please try again.'))}).catch(()=>fail('Network error. Please check your connection and try again.'))}}}document.getElementById('courseGrid').onclick=e=>{const b=e.target.closest('button[data-action]');if(b)openModal(Number(b.closest('[data-index]').dataset.index),b.dataset.action)};document.getElementById('filters').onclick=e=>{let b=e.target.closest('button[data-filter]');if(!b)return;document.querySelectorAll('#filters button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-group]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.group!==b.dataset.filter)};document.getElementById('closeModal').onclick=closeModal;modal.onclick=e=>{if(e.target===modal)closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});</script><script>document.addEventListener('DOMContentLoaded',()=>{if(!('IntersectionObserver' in window))return;const nodes=document.querySelectorAll('.ra-service,.ra-step,.course-card,.course-card-home,.contact-card,.card,.feature-card,.section-head');const io=new IntersectionObserver(items=>{items.forEach(i=>{if(i.isIntersecting){i.target.classList.add('ra-visible');io.unobserve(i.target)}})},{threshold:.08});nodes.forEach((el,i)=>{el.classList.add('ra-reveal');el.style.setProperty('--ra-delay',(i%3)*90+'ms');io.observe(el)})});</script>
